YUI.add('moodle-availability_rvspayment-form',function(Y,NAME){M.availability_rvspayment=M.availability_rvspayment||{};M.availability_rvspayment.form=Y.Object(M.core_availability.plugin);M.availability_rvspayment.form.defaultPrice=0;M.availability_rvspayment.form.currencies=[];M.availability_rvspayment.form.isSection=false;M.availability_rvspayment.form.initInner=function(defaultPrice,currencies,isSection){this.defaultPrice=defaultPrice;this.currencies=currencies;this.isSection=isSection;};M.availability_rvspayment.form.getNode=function(json){var currencyOptions='';for(var i=0;i<this.currencies.length;i++){var curr=this.currencies[i];var selected=(json.currency===curr.code)?' selected':'';currencyOptions+='<option value="'+curr.code+'"'+selected+'>'+curr.name+'</option>';}var html='<span class="col-form-label p-r-1">'+M.util.get_string('title','availability_rvspayment')+'</span>';html+='<span class="availability-group form-group">';html+='<label class="form-check form-check-inline">';html+='<input type="checkbox" class="form-check-input" name="isfree"';if(json.isfree){html+=' checked';}html+='>';html+='<span class="form-check-label">'+M.util.get_string('label_isfree','availability_rvspayment')+'</span>';html+='</label>';html+='</span>';html+='<span class="availability-group form-group rvspayment-price-group">';html+='<label>';html+='<span class="accesshide">'+M.util.get_string('label_price','availability_rvspayment')+'</span>';html+='<input type="number" class="form-control" name="price" min="0" step="1" ';html+='placeholder="'+M.util.get_string('label_price','availability_rvspayment')+'" ';html+='title="'+M.util.get_string('label_price','availability_rvspayment')+'" ';html+='value="'+(json.price!==undefined?json.price:this.defaultPrice)+'" ';html+='style="width:100px;display:inline-block;">';html+='</label>';html+=' <label>';html+='<span class="accesshide">'+M.util.get_string('label_currency','availability_rvspayment')+'</span>';html+='<select class="form-control custom-select" name="currency" title="'+M.util.get_string('label_currency','availability_rvspayment')+'">';html+=currencyOptions;html+='</select>';html+='</label>';html+='</span>';if(this.isSection){html+='<span class="availability-group form-group">';html+='<label class="form-check form-check-inline">';html+='<input type="checkbox" class="form-check-input" name="requireprevious"';if(json.requireprevious){html+=' checked';}html+='>';html+='<span class="form-check-label">'+M.util.get_string('label_requireprevious','availability_rvspayment')+'</span>';html+='</label>';html+='</span>';}var node=Y.Node.create('<span class="d-flex flex-wrap align-items-center">'+html+'</span>');var updatePriceVisibility=function(){var isFree=node.one('input[name=isfree]').get('checked');var priceGroup=node.one('.rvspayment-price-group');if(priceGroup){if(isFree){priceGroup.setStyle('display','none');}else{priceGroup.setStyle('display','');}}};updatePriceVisibility();if(!M.availability_rvspayment.form.addedEvents){M.availability_rvspayment.form.addedEvents=true;var root=Y.one('.availability-field');root.delegate('change',function(){M.core_availability.form.update();},'.availability_rvspayment select, .availability_rvspayment input');root.delegate('keyup',function(){M.core_availability.form.update();},'.availability_rvspayment input[name=price]');}node.one('input[name=isfree]').on('change',function(){updatePriceVisibility();M.core_availability.form.update();});return node;};M.availability_rvspayment.form.fillValue=function(value,node){var isFree=node.one('input[name=isfree]').get('checked');value.isfree=isFree;if(!isFree){var priceInput=node.one('input[name=price]');value.price=parseFloat(priceInput.get('value'))||0;var currencySelect=node.one('select[name=currency]');value.currency=currencySelect.get('value');}else{value.price=0;value.currency='KES';}var requirePrevious=node.one('input[name=requireprevious]');if(requirePrevious){value.requireprevious=requirePrevious.get('checked');}else{value.requireprevious=false;}};M.availability_rvspayment.form.fillErrors=function(errors,node){var isFree=node.one('input[name=isfree]').get('checked');if(!isFree){var price=parseFloat(node.one('input[name=price]').get('value'));if(isNaN(price)||price<=0){errors.push('availability_rvspayment:error_setprice');}}};},'@VERSION@',{"requires":["base","node","event","moodle-core_availability-form"]});
